import {formatCurrencyInput,parseCurrencyInput} from './currency-input.js';
import {PROVINCES,estimatePayroll,salaryIncomeTaxRates,payrollSources} from './planner-payroll.js';
import {CADENCES,PLANNER_LIMITS,plannerBudgetSources,annualize,summarizeBudget,roomAnalysis,rrspNewRoom,createDefaultPlannerState,validatePlannerState} from './planner-budget.js';
export const plannerSources=[...payrollSources,...plannerBudgetSources];
const currency=n=>new Intl.NumberFormat('en-CA',{style:'currency',currency:'CAD',maximumFractionDigits:2,minimumFractionDigits:2}).format(n);
const short=n=>new Intl.NumberFormat('en-CA',{style:'currency',currency:'CAD',maximumFractionDigits:0}).format(n);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const records=new Map();
let idCounter=0;
const uid=()=>globalThis.crypto?.randomUUID?.()??Date.now().toString(36)+'-'+(++idCounter).toString(36)+'-'+Math.random().toString(36).slice(2,10);
const storageKey=mode=>'money-side-quests:planner:'+mode+':v1';
function record(mode){if(records.has(mode))return records.get(mode);const r={state:createDefaultPlannerState(),saved:true,notice:'',confirm:false,undo:null,roomsOpen:false};try{const raw=localStorage.getItem(storageKey(mode));if(raw){const result=validatePlannerState(JSON.parse(raw));if(result.valid)r.state=result.value;else r.notice='The saved planner could not be restored. Your lesson progress is unchanged.'}}catch{r.saved=false;r.notice='Saved planner data is unavailable. You can still plan in this session.'}records.set(mode,r);return r}
function save(r,mode){try{localStorage.setItem(storageKey(mode),JSON.stringify(r.state));r.saved=true}catch{r.saved=false}}
function model(r){const s=r.state;const base=estimatePayroll({salary:s.salary??0,province:s.province??'ON'});const summary=summarizeBudget(s.categories,Math.max(0,base.takeHome));const room=roomAnalysis({...s,totals:summary.registeredTotals});const after=estimatePayroll({salary:s.salary??0,province:s.province??'ON',rrspDeduction:room.deductibleRRSP,fhsaDeduction:room.deductibleFHSA});return {base,summary,room,after,taxRates:salaryIncomeTaxRates({salary:s.salary??0,province:s.province??'ON'}),taxSaving:Math.max(0,base.tax-after.tax)}}
const numberField=(label,key,value,{min=0,max=10000000,step=.01,optional=false,hint=''}={})=>`<label class="planner-field"><span>${label}</span><input type="text" inputmode="decimal" data-money data-plan-field="${key}" value="${formatCurrencyInput(value)}" min="${min}" max="${max}" step="${step}" ${optional?'placeholder="Not entered"':'required'} aria-label="${label}">${hint?'<small>'+hint+'</small>':''}</label>`;
function payrollDetails(m,s){return `<div class="planner-pay-strip"><div><span>Estimated monthly take-home</span><strong>${currency(m.base.takeHome/12)}</strong><small>${currency(m.base.takeHome)} per year</small></div><div><span>Estimated monthly income tax</span><strong>${currency(m.base.tax/12)}</strong><small>Before planned account deductions</small></div></div><div class="planner-payroll-deductions"><div><span>${s.province==='QC'?'QPP + QPP2':'CPP + CPP2'} / month</span><strong>− ${currency(((m.base.cpp??0)+(m.base.cpp2??0))/12)}</strong></div><div><span>EI / month</span><strong>− ${currency(m.base.ei/12)}</strong></div>${s.province==='QC'?'<div><span>QPIP / month</span><strong>− '+currency(m.base.qpip/12)+'</strong></div>':''}</div><div class="planner-tax-rate-grid"><div><span>Average income-tax rate</span><strong>${(m.taxRates.average*100).toFixed(2)}%</strong><small>Income tax ÷ gross salary</small></div><div><span>Marginal income-tax rate</span><strong>${(m.taxRates.marginal*100).toFixed(2)}%</strong><small>Estimated tax on the next $100 of gross salary</small></div></div><p class="planner-rate-note">Both rates exclude CPP/QPP, EI and QPIP payments. The marginal estimate includes the effect of salary-based credits and deductions, and may span a nearby bracket threshold. Rates are before your planned registered-account deductions.</p><p class="planner-payroll-caption">Take-home = gross salary − income tax − ${s.province==='QC'?'QPP/QPP2 − EI − QPIP':'CPP/CPP2 − EI'}. These deductions are already removed from your budget baseline.</p><details class="planner-details"><summary>See the salary breakdown</summary><div class="table-scroll"><table><tbody>${[['Annual gross salary',m.base.gross],['Federal income tax',m.base.federalTax],['Provincial / territorial income tax',m.base.provincialTax],[s.province==='QC'?'QPP (including additional contributions)':'CPP (including additional contributions)',(m.base.cpp??0)+(m.base.cpp2??0)],['Employment Insurance',m.base.ei],...(s.province==='QC'?[['Québec parental insurance (QPIP)',m.base.qpip??0]]:[]),['Estimated take-home before savings',m.base.takeHome]].map(([l,v])=>`<tr><th>${l}</th><td>${currency(v??0)}</td></tr>`).join('')}</tbody></table></div></details>${['NB','NL','NS','PE'].includes(s.province)?'<p class="planner-estimate-note">This province’s low-income tax reduction is not included. The estimate may overstate tax at lower incomes. See the assumptions below.</p>':s.province==='QC'?'<p class="planner-estimate-note">Québec estimate includes QPP and QPIP, but excludes RAMQ premiums and certain personal/refundable credits. See the assumptions below.</p>':['NT','NU','YT'].includes(s.province)?'<p class="planner-estimate-note">Northern residents deductions and territorial refundable credits are not included. See the assumptions below.</p>':''}`}
function roomEstimate(s){const actual=rrspNewRoom(s.priorEarnedIncome,s.pensionAdjustment);const assumed=rrspNewRoom(s.salary??0,0);return actual===null?`<strong>Salary-based illustration: ${currency(assumed)} of ordinary new RRSP room.</strong><p>This assumes your 2025 earned income equalled the salary above and no pension adjustment. It is not your confirmed 2026 room. Enter prior-year details below for a better illustration; carryforward and other adjustments still need your records.</p>`:`<strong>Illustrative new 2026 RRSP room: ${currency(actual)}.</strong><p>max(0, min(18% × 2025 earned income, $33,810) − 2025 pension adjustment). This excludes carryforward, unused contributions and other adjustments; it does not replace your CRA figures.</p>`}
function incomeStep(r,m){const s=r.state;return `<section class="planner-panel"><div class="planner-panel-title"><span class="planner-step-icon">01</span><div><h2>Start with what comes in.</h2><p>Enter annual employment income. We’ll estimate a 2026 budget baseline.</p></div></div><div class="planner-form-grid">${numberField('Annual gross salary ($)','salary',s.salary,{max:1000000,step:.01,hint:'Example starts at $80,000. Replace it with your salary.'})}<label class="planner-field"><span>Province / territory of residence</span><select data-plan-field="province" aria-label="Province / territory of residence">${PROVINCES.map(p=>`<option value="${p.code}" ${s.province===p.code?'selected':''}>${esc(p.name)}</option>`).join('')}</select><small>Assumes the same province for work and residence.</small></label></div><div data-income-live>${payrollDetails(m,s)}</div><div class="planner-divider"></div><div class="planner-panel-title"><div><h2>Registered accounts: limits ≠ personal room.</h2><p>Salary helps estimate ordinary new RRSP room. Eligibility, past transactions and carryforward determine what you can actually contribute.</p></div></div><div class="planner-limit-grid"><article><span>TFSA · 2026 new annual limit</span><strong>${short(PLANNER_LIMITS.tfsaAnnual)}</strong><p>Unused eligible room and prior-year withdrawals can change your personal amount.</p></article><article><span>RRSP · 2026 new-room ceiling</span><strong>${short(PLANNER_LIMITS.rrspNewRoomMaximum)}</strong><p>Based on 18% of prior-year earned income, subject to pension and other adjustments.</p></article><article><span>FHSA · new annual / lifetime</span><strong>${short(PLANNER_LIMITS.fhsaNewRoom)} / ${short(PLANNER_LIMITS.fhsaLifetime)}</strong><p>Eligible account holders only. Ordinary carryforward is capped at $8,000.</p></article></div><div class="planner-room-estimate" data-room-estimate>${roomEstimate(s)}</div><details class="planner-details" ${r.roomsOpen?'open':''}><summary>Confirm available room & deduction inputs</summary><p class="planner-help">Optional until you budget registered savings. Enter room remaining before the new contributions in this plan, after accounting for transactions elsewhere. Blank means unknown; $0 means no room. CRA records can lag—reconcile them with your own records. No account sign-in is needed here.</p><div class="planner-form-grid">${numberField('2025 earned income ($)','priorEarnedIncome',s.priorEarnedIncome,{optional:true})}${numberField('2025 pension adjustment ($)','pensionAdjustment',s.pensionAdjustment)}</div><div class="planner-room-group"><h3>TFSA</h3>${numberField('Confirmed available TFSA room ($)','tfsaRoom',s.tfsaRoom,{optional:true})}</div><div class="planner-room-group"><h3>RRSP</h3><div class="planner-form-grid">${numberField('Confirmed available RRSP contribution room ($)','rrspRoom',s.rrspRoom,{optional:true})}${numberField('Available RRSP deduction room for new contributions ($)','rrspDeductionRoom',s.rrspDeductionRoom,{optional:true})}</div><p class="planner-help">Contribution and deduction room can differ when you have previously contributed but undeducted amounts. This tool models new cash contributions only.</p></div><div class="planner-room-group"><h3>FHSA</h3><label class="planner-check"><input type="checkbox" data-plan-eligible ${s.fhsaEligible?'checked':''}> I confirm FHSA eligibility and that an FHSA is open.</label>${s.fhsaEligible?`<div class="planner-form-grid">${numberField('Confirmed available FHSA participation room ($)','fhsaRoom',s.fhsaRoom,{optional:true})}${numberField('Available FHSA deduction room for new cash ($)','fhsaDeductionRoom',s.fhsaDeductionRoom,{optional:true})}${numberField('FHSA lifetime contributions + RRSP transfers already used ($)','fhsaLifetimeUsed',s.fhsaLifetimeUsed,{max:40000})}</div>`:'<p class="planner-help">FHSA categories can be planned, but no deduction will be included until eligibility and room are confirmed.</p>'}</div></details><div class="planner-next"><span>Everything stays in this browser.</span><button class="primary" data-plan-next>Build my budget →</button></div></section>`}
function color(c){const palette=c.kind==='saving'?['#31745a','#57966d','#83af84','#25736a','#6b9e5c','#a3c399']:['#b34f43','#d16c58','#a75e56','#e58e6e','#cc785a','#a33f49'];const n=[...c.id].reduce((x,ch)=>x+ch.charCodeAt(0),0);return palette[n%palette.length]}
function categoryRow(c,m){const periods=CADENCES.find(x=>x.id===c.cadence).periods,max=Math.max(100,c.amount,Math.ceil(m.base.takeHome/periods*1.5/100)*100);return `<article class="planner-category ${c.kind}" data-category="${c.id}" style="--category-color:${color(c)}"><div class="planner-category-top"><label><span class="sr-only">Category name</span><input type="text" data-cat-field="name" value="${esc(c.name)}" maxlength="80" aria-label="Category name: ${esc(c.name)}"></label><button class="planner-icon-button" data-remove-category="${c.id}" aria-label="Remove ${esc(c.name)}">×</button></div><div class="planner-category-options"><label><span>Type</span><select data-cat-field="kind" aria-label="Type for ${esc(c.name)}"><option value="expense" ${c.kind==='expense'?'selected':''}>Expense</option><option value="saving" ${c.kind==='saving'?'selected':''}>Saving</option></select></label><label><span>Cadence</span><select data-cat-field="cadence" aria-label="Cadence for ${esc(c.name)}">${CADENCES.map(x=>`<option value="${x.id}" ${c.cadence===x.id?'selected':''}>${x.label}</option>`).join('')}</select></label>${c.kind==='saving'?`<label><span>Account</span><select data-cat-field="account" aria-label="Savings account for ${esc(c.name)}">${[['unregistered','Unregistered / cash'],['tfsa','TFSA'],['rrsp','RRSP'],['fhsa','FHSA']].map(([id,l])=>`<option value="${id}" ${c.account===id?'selected':''}>${l}</option>`).join('')}</select></label>`:`<label><span>Payment · optional</span><select data-cat-field="payment" aria-label="Payment method for ${esc(c.name)}">${[['unspecified','Not specified'],['debit','Debit / cash'],['credit','Credit card']].map(([id,l])=>`<option value="${id}" ${c.payment===id?'selected':''}>${l}</option>`).join('')}</select></label>`}</div><div class="planner-category-amount"><span>${c.kind==='saving'?'Set aside':'Spend'} each ${c.cadence==='annually'?'year':c.cadence==='quarterly'?'quarter':c.cadence==='biweekly'?'two weeks':c.cadence==='weekly'?'week':'month'}</span><label><input type="text" inputmode="decimal" data-money data-cat-field="amount" min="0" max="10000000" step=".01" value="${formatCurrencyInput(c.amount)}" aria-label="Amount for ${esc(c.name)}"></label></div><input class="planner-category-slider" type="range" data-cat-slider min="0" max="${max}" step="1" value="${c.amount}" aria-label="Budget slider for ${esc(c.name)}"><div class="planner-category-foot" data-category-equivalent>${currency(annualize(c.amount,c.cadence)/12)} / month · ${currency(annualize(c.amount,c.cadence))} / year</div></article>`}
function categoriesStep(r,m){return `<section class="planner-panel"><div class="planner-panel-title"><span class="planner-step-icon">02</span><div><h2>Give every dollar a direction.</h2><p>Mix cadences freely. We’ll convert everything to the same annual budget.</p></div></div><div class="planner-category-list">${r.state.categories.length?r.state.categories.map(c=>categoryRow(c,m)).join(''):`<div class="planner-empty"><span>✳</span><h3>A clean slate for your money.</h3><p>Add a category for rent, groceries, a holiday or future you. The chart will grow with your plan.</p></div>`}</div><div class="planner-add-actions"><button class="planner-add expense" data-add-category="expense" ${r.state.categories.length>=50?'disabled':''}>＋ Add expense</button><button class="planner-add saving" data-add-category="saving" ${r.state.categories.length>=50?'disabled':''}>＋ Add saving</button></div>${r.undo?'<div class="planner-undo">Category removed. <button class="plain" data-plan-undo>Undo</button></div>':''}<p class="planner-help">Weekly × 52 · Every two weeks × 26 · Monthly × 12 · Quarterly × 4 · Annually × 1. Credit is a payment label, not extra income. Avoid budgeting the same card purchases and their full repayment twice; existing debt repayments or card interest can have their own categories.</p><div class="planner-next"><button class="plain" data-plan-income>← Edit income & room</button><button class="plain" data-plan-add-example ${r.state.categories.length?'disabled':''}>Try a sample budget</button></div></section>`}
function pie(m){const total=Math.max(m.base.takeHome,m.summary.allocatedAnnual),rows=m.summary.categories.filter(c=>c.annual>0);let cursor=0;const stops=rows.map(c=>{const start=cursor;cursor+=total>0?c.annual/total*100:0;return `${color(c)} ${start.toFixed(5)}% ${cursor.toFixed(5)}%`});if(cursor<100)stops.push(`#e7e3ec ${cursor.toFixed(5)}% 100%`);if(!stops.length)stops.push('#e7e3ec 0% 100%');const used=m.base.takeHome>0?m.summary.allocatedAnnual/m.base.takeHome*100:0;return `<div class="planner-donut-wrap"><div class="planner-donut" role="img" aria-label="${esc('Budget allocation. Expenses '+currency(m.summary.expenseAnnual)+', savings '+currency(m.summary.savingAnnual)+', '+(m.summary.remainingAnnual>=0?'unallocated '+currency(m.summary.remainingAnnual):'over budget by '+currency(m.summary.overspendAnnual))+'. Exact categories are listed below.') }" style="background:conic-gradient(${stops.join(',')})"><div><small>TAKE-HOME ALLOCATED</small><strong>${m.base.takeHome===0&&m.summary.allocatedAnnual>0?'No income':used.toFixed(0)+'%'}</strong><span>${short(m.summary.allocatedAnnual/12)} / month</span></div></div></div>`}
function chartPanel(m){const over=m.summary.overspendAnnual>0;return `<div class="planner-summary-heading"><div><div class="eyebrow">YOUR MONEY, AT A GLANCE</div><h2>A plan you can see.</h2></div><span class="planner-year">2026</span></div><div class="planner-income-baseline"><span>Monthly available after tax, CPP/QPP & EI</span><strong>${currency(m.base.takeHome/12)}</strong></div>${pie(m)}${over?`<div class="planner-over">Over budget by <strong>${currency(m.summary.overspendAnnual/12)} / month</strong><small>Pie slices show shares of allocations when they exceed income. Percentages below still use take-home pay.</small></div>`:`<div class="planner-remaining"><span>Still available each month</span><strong>${currency(m.summary.remainingAnnual/12)}</strong></div>`}<div class="planner-totals"><div><i class="expense-dot"></i><span>Expenses</span><strong>${short(m.summary.expenseAnnual/12)} / mo</strong></div><div><i class="saving-dot"></i><span>Savings</span><strong>${short(m.summary.savingAnnual/12)} / mo</strong></div></div><div class="planner-legend">${m.summary.categories.map(c=>`<div><i style="background:${color(c)}"></i><span>${esc(c.name)}<small>${c.kind==='saving'?(c.account==='unregistered'?'Unregistered saving':c.account.toUpperCase()):'Expense'+(c.payment==='unspecified'?'':' · '+esc(c.payment))}</small></span><strong>${currency(c.monthly)}<small>${m.base.takeHome>0?(c.shareOfIncome*100).toFixed(1)+'% of take-home':'No income baseline'}</small></strong></div>`).join('')||'<p class="planner-help">Your categories will appear here.</p>'}${!over&&m.summary.remainingAnnual>0?`<div><i style="background:#e7e3ec"></i><span>Unallocated</span><strong>${short(m.summary.remainingAnnual/12)}<small>${m.base.takeHome>0?(m.summary.remainingAnnual/m.base.takeHome*100).toFixed(1):'0'}%</small></strong></div>`:''}</div><p class="planner-chart-note">Legend amounts are monthly equivalents. Expense colours are warm; saving colours are green. CPP/QPP, EI and any QPIP are already deducted. No refund is added to this cash budget.</p>`}
function taxPanel(r,m){const s=r.state,totalDed=m.after.appliedRRSP+m.after.appliedFHSA,annualRefund=s.withheldTax===null?null:s.withheldTax-m.after.tax;return `<div class="planner-tax-heading"><span>↗</span><div><div class="eyebrow">CONTRIBUTIONS & TAX</div><h2>Your possible tax relief.</h2></div></div><div class="planner-tax-highlight"><span>Estimated annual income-tax reduction</span><strong>${currency(m.taxSaving)}</strong><small>${currency(m.taxSaving/12)} monthly equivalent · not included in the budget above</small></div><div class="planner-tax-lines"><p><span>RRSP deduction modelled</span><strong>${currency(m.after.appliedRRSP)}</strong></p><p><span>FHSA deduction modelled</span><strong>${currency(m.after.appliedFHSA)}</strong></p><p><span>Income tax after these deductions</span><strong>${currency(m.after.tax)}</strong></p></div>${m.room.deductibleRRSP+m.room.deductibleFHSA>totalDed?'<p class="planner-help">'+currency(m.room.deductibleRRSP+m.room.deductibleFHSA-totalDed)+' of room-eligible contributions is not applied against this year’s modelled income. Check account-specific unused-deduction and carryforward rules.</p>':''}${m.room.flags.length?`<div class="planner-room-alerts">${m.room.flags.map(f=>`<p><strong>${f.account.toUpperCase()} ${f.type==='excess'?'room exceeded':f.type==='unknown'?'room not confirmed':'eligibility not confirmed'}</strong><span>${esc(f.message)}${f.excess?' Excess: '+currency(f.excess)+'.':''}</span></p>`).join('')}<button class="plain" data-plan-confirm-room>Check room inputs →</button></div>`:''}<p class="planner-help">TFSA and unregistered savings have no contribution deduction. Tax relief is calculated only on new RRSP/FHSA cash contributions within confirmed room and deduction inputs. ${totalDed===0?'No eligible deduction is currently modelled. ':''}Excess or unconfirmed contributions remain in your cash budget; they are not treated as permitted.</p><details class="planner-details"><summary>Turn tax relief into an estimated refund</summary><p class="planner-help">If tax withheld equals the baseline estimate, the extra refund from these deductions would be about ${currency(m.taxSaving)}. If payroll already reduced withholding for them, don’t count that benefit twice.</p>${numberField('Annual income tax withheld / expected ($)','withheldTax',s.withheldTax,{optional:true,hint:'Exclude CPP/QPP, EI and QPIP. Leave blank if unknown.'})}<div data-refund-result>${annualRefund===null?'<p class="planner-help">Enter withholding to estimate a refund or balance owing under this model.</p>':`<div class="planner-refund-result"><span>Model ${annualRefund>=0?'refund':'balance owing'}</span><strong>${currency(Math.abs(annualRefund))}</strong></div>`}</div><p class="planner-help">Estimated refund = entered income tax withheld − estimated tax after deductions. Other income, credits, benefits, deductions and prior transactions can change a filed return.</p></details><details class="planner-details"><summary>Annual registered savings & room check</summary><div class="table-scroll"><table><thead><tr><th>Account</th><th>Planned cash</th><th>Confirmed allowance</th><th>Room after plan</th></tr></thead><tbody>${['tfsa','rrsp','fhsa'].map(id=>`<tr><th>${id.toUpperCase()}</th><td>${currency(m.summary.registeredTotals[id])}</td><td>${m.room.details[id].limit===null?'Unknown':currency(m.room.details[id].limit)}</td><td>${m.room.details[id].limit===null?'Unknown':m.room.details[id].planned>m.room.details[id].limit?'Over '+currency(m.room.details[id].planned-m.room.details[id].limit):currency(m.room.details[id].limit-m.room.details[id].planned)}</td></tr>`).join('')}</tbody></table></div><p class="planner-help">Unused confirmed room is not carried into other accounts. No RRSP-to-FHSA transfers or previously undeducted contributions are modelled.</p></details>`}
function assumptions(m){const notes=[...(m.base.assumptions??[]),...(m.base.notes??[])];return `<details class="planner-assumptions"><summary>What this planner assumes</summary><p>Tax year 2026. Standard salaried employee aged 18–64, single with no dependants, one employer, full-year Canadian residence, and the same province for work and residence. Employment benefits, union dues, pension contributions, bonuses, other income and special tax credits are not entered. Estimates can differ from actual pay slips or a filed tax return.</p>${Array.isArray(notes)?notes.map(note=>'<p>'+esc(typeof note==='string'?note:JSON.stringify(note))+'</p>').join(''):'<p>'+esc(notes)+'</p>'}<p>The budget uses baseline take-home before your planned RRSP/FHSA deduction benefit. Savings are cash outflows; any tax refund is a separate future cash flow. All calculations stay in your browser. Rates are fixed for 2026 and do not update automatically.</p><button class="plain" data-drawer="sources">Official rates & room sources ↗</button></details>`}
export function renderPlanner(mode='workshop'){const r=record(mode),m=model(r);return `<section class="planner-intro"><div><div class="eyebrow">A TOOL FOR REAL LIFE · SEPARATE FROM THE LESSONS</div><h1>Your money. Your priorities.</h1><p>Turn a salary into a plan—with room for everyday life and future you.</p></div><span class="planner-save" data-planner-save>${r.saved?'◌ Saved locally':'◌ Session only · storage unavailable'}</span></section>${r.notice?'<div class="banner">'+esc(r.notice)+'</div>':''}<div class="planner-steps" aria-label="Budget planner steps"><button class="${r.state.step===1?'active':''}" data-plan-income><b>1</b> Income & accounts</button><span>→</span><button class="${r.state.step!==1?'active':''}" data-plan-next><b>2</b> Build your budget</button><small>No sign-in. No bank connection.</small></div><div class="planner-layout"><div class="planner-left">${r.state.step===1?incomeStep(r,m):categoriesStep(r,m)}${assumptions(m)}</div><aside class="planner-right"><section class="planner-chart-panel" data-planner-chart>${chartPanel(m)}</section><section class="planner-tax-panel" data-planner-tax>${taxPanel(r,m)}</section></aside></div>${r.confirm?`<div class="modal-wrap"><section class="modal planner-confirm" role="dialog" aria-modal="true" aria-labelledby="planner-reset-title"><h2 id="planner-reset-title">Reset this budget planner?</h2><p>This clears the ${mode==='demo'?'demo':'saved'} planner’s income, categories and room inputs. Your learning-module progress is kept.</p><div class="modal-actions"><button class="plain" data-plan-cancel-reset>Keep my plan</button><button class="primary" data-plan-confirm-reset>Reset planner</button></div></section></div>`:''}`}
function updateResults(r,mode,root){const m=model(r);const replace=(selector,markup)=>{const el=root.querySelector(selector);if(el)el.innerHTML=markup};replace('[data-planner-chart]',chartPanel(m));const oldTax=root.querySelector('[data-planner-tax]');if(oldTax){const active=document.activeElement;const editingWithholding=active?.dataset?.planField==='withheldTax';if(!editingWithholding){const openDetails=[...oldTax.querySelectorAll('details')].map(d=>d.open);oldTax.innerHTML=taxPanel(r,m);oldTax.querySelectorAll('details').forEach((d,i)=>d.open=!!openDetails[i]);bindDynamic(r,mode,root)}else{const refund=r.state.withheldTax===null?null:r.state.withheldTax-m.after.tax;replace('[data-refund-result]',refund===null?'<p class="planner-help">Enter withholding to estimate a refund or balance owing.</p>':`<div class="planner-refund-result"><span>Model ${refund>=0?'refund':'balance owing'}</span><strong>${currency(Math.abs(refund))}</strong></div>`)}}replace('[data-income-live]',payrollDetails(m,r.state));replace('[data-room-estimate]',roomEstimate(r.state));root.querySelectorAll('[data-category]').forEach(el=>{const c=r.state.categories.find(c=>c.id===el.dataset.category);if(!c)return;const names={name:'Category name: ',kind:'Type for ',cadence:'Cadence for ',account:'Savings account for ',payment:'Payment method for ',amount:'Amount for '};el.querySelectorAll('[data-cat-field]').forEach(e=>e.setAttribute('aria-label',names[e.dataset.catField]+c.name));el.querySelector('[data-cat-slider]').setAttribute('aria-label','Budget slider for '+c.name);el.querySelector('[data-remove-category]').setAttribute('aria-label','Remove '+c.name);el.querySelector('[data-category-equivalent]').textContent=currency(annualize(c.amount,c.cadence)/12)+' / month · '+currency(annualize(c.amount,c.cadence))+' / year';const slider=el.querySelector('[data-cat-slider]'),number=el.querySelector('[data-cat-field="amount"]');if(document.activeElement!==slider){slider.max=Math.max(100,c.amount,+slider.max);slider.value=c.amount}if(document.activeElement!==number)number.value=formatCurrencyInput(c.amount)});root.querySelector('[data-planner-save]').textContent=r.saved?'◌ Saved locally':'◌ Session only · storage unavailable'}
let rerender=()=>{};
function bindDynamic(r,mode,root){root.querySelectorAll('[data-plan-confirm-room]').forEach(b=>b.onclick=()=>{r.roomsOpen=true;r.state.step=1;save(r,mode);rerender();window.scrollTo(0,0)});const field=root.querySelector('[data-plan-field="withheldTax"]');if(field)bindField(field,r,mode,root)}
function readAmount(e){const value=parseCurrencyInput(e.value),min=Number(e.getAttribute('min')??0),max=Number(e.getAttribute('max')??10000000);const valid=value===null?!e.required:Number.isFinite(value)&&value>=min&&value<=max;e.setCustomValidity(valid?'':'Enter a valid dollar amount between '+formatCurrencyInput(min)+' and '+formatCurrencyInput(max)+'.');return {valid,value}}
function moneyEditing(e,getValue){e.onfocus=()=>{const value=getValue();e.value=value===null||value===undefined?'':String(value);e.select()};e.onblur=()=>{const amount=readAmount(e);if(amount.valid)e.value=formatCurrencyInput(getValue());else e.reportValidity()}}
function bindField(e,r,mode,root){if(e.tagName!=='SELECT')moneyEditing(e,()=>r.state[e.dataset.planField]);e.oninput=()=>{const key=e.dataset.planField;if(e.tagName==='SELECT'){r.state[key]=e.value;save(r,mode);rerender();return}const amount=readAmount(e);if(!amount.valid)return;r.state[key]=amount.value;save(r,mode);updateResults(r,mode,root)}}
export function bindPlanner({mode='workshop',onRender,root=document}={}){rerender=onRender;const r=record(mode);root.querySelectorAll('[data-plan-field]').forEach(e=>bindField(e,r,mode,root));root.querySelector('[data-plan-eligible]')?.addEventListener('change',e=>{r.state.fhsaEligible=e.target.checked;r.roomsOpen=true;save(r,mode);onRender()});root.querySelectorAll('[data-plan-next]').forEach(b=>b.onclick=()=>{const salary=root.querySelector('[data-plan-field="salary"]');if(salary&&(!readAmount(salary).valid||!salary.checkValidity()||salary.value==='')){salary.reportValidity();return}r.state.step=2;save(r,mode);onRender();window.scrollTo(0,0)});root.querySelectorAll('[data-plan-income]').forEach(b=>b.onclick=()=>{r.state.step=1;save(r,mode);onRender();window.scrollTo(0,0)});root.querySelectorAll('[data-add-category]').forEach(b=>b.onclick=()=>{if(r.state.categories.length>=50)return;const kind=b.dataset.addCategory;r.state.categories.push({id:'c-'+uid(),name:kind==='saving'?'New saving':'New expense',kind,cadence:'monthly',amount:0,account:'unregistered',payment:'unspecified'});save(r,mode);onRender();root.querySelector('[data-category]:last-child [data-cat-field="name"]')?.focus()});root.querySelectorAll('[data-remove-category]').forEach(b=>b.onclick=()=>{const i=r.state.categories.findIndex(c=>c.id===b.dataset.removeCategory);r.undo={category:r.state.categories[i],index:i};r.state.categories.splice(i,1);save(r,mode);onRender()});root.querySelector('[data-plan-undo]')?.addEventListener('click',()=>{if(r.undo&&r.state.categories.length<50)r.state.categories.splice(r.undo.index,0,r.undo.category);r.undo=null;save(r,mode);onRender()});root.querySelectorAll('[data-category]').forEach(el=>{const c=r.state.categories.find(c=>c.id===el.dataset.category);el.querySelectorAll('[data-cat-field]').forEach(e=>{const key=e.dataset.catField;if(e.tagName==='SELECT')e.onchange=()=>{c[key]=e.value;if(c.kind==='expense')c.account='unregistered';else c.payment='unspecified';save(r,mode);onRender()};else {if(key==='name')e.onblur=()=>{if(!e.value.trim())e.value=c.name};else moneyEditing(e,()=>c.amount);e.oninput=()=>{if(key==='name'){if(!e.value.trim())return;c.name=e.value.trim().slice(0,80)}else{const amount=readAmount(e);if(!amount.valid||amount.value===null)return;c.amount=amount.value}save(r,mode);updateResults(r,mode,root)}}});el.querySelector('[data-cat-slider]').oninput=e=>{c.amount=+e.target.value;save(r,mode);updateResults(r,mode,root)}});root.querySelector('[data-plan-add-example]')?.addEventListener('click',()=>{if(r.state.categories.length)return;const monthly=model(r).base.takeHome/12;const make=(name,kind,amount,cadence,account='unregistered')=>({id:'c-'+uid(),name,kind,amount:Math.round(amount),cadence,account,payment:'unspecified'});r.state.categories=[make('Home & utilities','expense',monthly*.35,'monthly'),make('Groceries','expense',monthly*.12*12/52,'weekly'),make('Getting around','expense',monthly*.08,'monthly'),make('Fun & everyday life','expense',monthly*.10,'monthly'),make('Emergency fund','saving',monthly*.10,'monthly'),make('Long-term savings','saving',monthly*.10,'monthly')];save(r,mode);onRender()});root.querySelectorAll('[data-planner-reset]').forEach(b=>b.onclick=()=>{r.confirm=true;onRender()});root.querySelector('[data-plan-cancel-reset]')?.addEventListener('click',()=>{r.confirm=false;onRender()});root.querySelector('[data-plan-confirm-reset]')?.addEventListener('click',()=>{r.state=createDefaultPlannerState();r.confirm=false;r.undo=null;r.notice='';save(r,mode);onRender();window.scrollTo(0,0)});const dialog=root.querySelector('.planner-confirm');if(dialog){dialog.querySelector('button').focus();dialog.onkeydown=e=>{if(e.key==='Escape'){r.confirm=false;onRender()}if(e.key==='Tab'){const buttons=dialog.querySelectorAll('button'),first=buttons[0],last=buttons[buttons.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}}}bindDynamic(r,mode,root)}
